-- An enum key part is four bytes, whatever its label: beside a 62-character label,
-- 2 688 characters of text holds.
-- @setup
CREATE TYPE ixm AS ENUM ('a_very_long_label_to_make_the_varlena_bigger_than_four_bytes_x', 'ok');
CREATE TABLE t (m ixm, a text);
CREATE INDEX t_i ON t (m, a);
INSERT INTO t VALUES ('a_very_long_label_to_make_the_varlena_bigger_than_four_bytes_x', '');
-- @test
SELECT m::text, length(a) FROM t;
